WITH exploded AS (SELECT id, customer_id, coupon_codes, item.product_id, item.qty, item.promo FROM carts LATERAL VIEW EXPLODE(items) x AS item) SELECT id, customer_id, coupon_codes, product_id, qty, promo, MAX(product_id) OVER (PARTITION BY customer_id) AS customer_id_max_product_id, RANK() OVER (PARTITION BY promo, customer_id ORDER BY qty) AS qty_rank, PERCENT_RANK() OVER (ORDER BY product_id NULLS FIRST) AS product_id_percent_rank, DENSE_RANK() OVER (PARTITION BY customer_id, promo ORDER BY product_id DESC) AS product_id_dense_rank FROM exploded;
